<?php
require_once dirname(__DIR__).'/Config/blog.php';
$projectVideos=[];
foreach(is_array($project['videos']??null)?$project['videos']:[] as $video){
    if(!is_array($video)||!is_string($video['url']??null))continue;
    $id=blogYoutubeId($video['url']);if(!$id)continue;
    $projectVideos[]=['id'=>$id,'short'=>($video['type']??'video')==='short','title'=>is_string($video['title']??null)&&trim($video['title'])!==''?$video['title']:'Project video'];
}
?>
<section class="pd-section pd-media-section" id="project-gallery"><h2>Project Gallery</h2><?php if($gallery): ?><div class="pd-media-grid"><?php foreach($gallery as $index=>$photo): ?><button type="button" class="pd-media-photo" data-gallery-src="<?= e($photo) ?>" aria-label="Open <?= e($project['title']) ?> photo <?= $index+1 ?>"><img src="<?= e($photo) ?>" alt="<?= e($project['title']) ?> &ndash; photo <?= $index+1 ?>" loading="lazy" width="600" height="400"><span>View photo &nearr;</span></button><?php endforeach; ?></div><?php else: ?><p>Project photos have not been added yet.</p><?php endif; ?></section>
<section class="pd-section pd-media-section" id="project-videos"><h2>Project Videos &amp; Shorts</h2><?php if(!empty($project['videos_are_inspiration'])): ?><p class="pd-disclaimer">Home and interior inspiration from Architectural Digest. These tours show other homes and illustrate design ideas; they are not videos of this sample project.</p><?php endif; ?><?php if($projectVideos): ?><div class="pd-media-grid project-video-grid"><?php foreach($projectVideos as $video): ?><article class="pd-media-video <?= $video['short']?'is-short':'' ?>"><iframe src="https://www.youtube-nocookie.com/embed/<?= e($video['id']) ?>" title="<?= e($video['title']) ?>" loading="lazy" allow="encrypted-media; picture-in-picture" allowfullscreen></iframe><span class="project-video-type"><?= $video['short']?'YouTube Short':'YouTube video' ?></span><h3><?= e($video['title']) ?></h3><a href="https://www.youtube.com/<?= $video['short']?'shorts/':'watch?v=' ?><?= e($video['id']) ?>" target="_blank" rel="noopener noreferrer">Watch on YouTube &nearr;</a></article><?php endforeach; ?></div><?php else: ?><p>No videos have been added yet. Explore the gallery or contact our team to arrange a viewing.</p><?php endif; ?></section>
<?php if($gallery): ?><dialog class="pd-lightbox" id="pd-lightbox" aria-label="Project image viewer"><button type="button" class="pd-lightbox-close" aria-label="Close image viewer"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button><button type="button" class="pd-lightbox-prev" aria-label="Previous image"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><figure><div class="pd-lightbox-stage"><img alt=""></div><figcaption></figcaption></figure><button type="button" class="pd-lightbox-next" aria-label="Next image"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button></dialog><?php endif; ?>
